function Case([string]$name,[scriptblock]$body){$script:total++;try{& $body;$script:passed++}catch{throw "$name : $($_.Exception.Message) [$($_.ScriptStackTrace)]"}}
function New-Fixture([string]$mode){
    $store=Join-Path $tmp ([guid]::NewGuid().ToString('N'));Initialize-RepatoTaskStore $store|Out-Null;New-RepatoTask $store $taskId 'synthetic independent validation' 'isolated fixture' 'qa/maya-qa-workflow' 'maya'|Out-Null
    $e=[pscustomobject][ordered]@{BuildRequestId=$buildId;SourceCommit=$commit;CandidateSourceCommit=$commit;EvidenceSource='FrozenCandidate';CandidateDirectory=$candidate;CandidateProvenancePath=$provenance;ArtifactPath=$dll;ArtifactSha256=$candidateHash;ManifestPath=$candidateManifest;ManifestSha256=$candidateManifestHash;DeploymentValidation=$false;ManifestIntegrityValidation=$false;QaIsolation=$false;RunnerManifestPath=$sourceManifest;RunnerManifestSha256=$manifestHash;OriginalRunnerManifestPath='C:\Repato-Autonomous\Worktrees\create-plan-views-buildfix-4f2cbba22ba9\QA\Repato.CreatePlanViews.TestRunner.addin'}
    $wf=[pscustomobject][ordered]@{workflowId=$workflowId;taskId=$taskId;workflowRevision=1;taskRevision=1;qaWorkflowId='create-plan-views-v1';testId='create-plan-views-v1';qaBuildStatus='succeeded';qaBuildRequest=[pscustomobject]@{BuildRequestId=$buildId;AuthenticatedBuildSource=[pscustomobject]@{RepositoryRoot=$repoRoot;ExpectedSourceCommit=$commit;ProjectRelativePath='Forma.RevitConnector.csproj'}};qaBuildEvidence=$e}
    Invoke-RepatoStoreMutation $store {param($d,$preview)$t=Find-RepatoTask $d $taskId;$t.status='in-progress';$t.workflowStage='build-checks';$t.approvalRequests=@();$t|Add-Member NoteProperty deploymentWorkflows ([object[]]@($wf)) -Force;$t|Add-Member NoteProperty deploymentValidationOperations ([object[]]@()) -Force;$d|Add-Member NoteProperty stagingRequestDispositions ([object[]]@([pscustomobject]@{RequestId=('9'*32);Disposition='unresolved-task-binding';RecordedUtc=(Get-RepatoUtc)})) -Force;$d}|Out-Null
    $task=Find-RepatoTask (Read-RepatoTaskStore $store) $taskId
    $health={ [pscustomobject]@{Ready=$true;User='RAMSAI\RepatoQA';SID='S-1-5-21-1031246752-3872016183-2454652381-1015';SessionId=2;UserInteractive=$true} }
    $preflight={ [pscustomobject]@{Succeeded=$true;ExecutionIdentity='RAMSAI\RepatoQA';RunnerManifestPath=$installedManifest;ExpectedRunnerManifestSha256=$manifestHash} }
    $revit={ @() };$counter=[pscustomobject]@{Calls=0;InvokerEntered=$false;InvokerError=$null;LastResponse=$null;Mode=$mode}
    $invoker={param($verified,$pending)$counter.Calls++|Out-Null;$counter.InvokerEntered=$true;try{$response=[pscustomobject][ordered]@{schemaVersion=1;operation='validate-qa-deployment';requestId=$pending.RequestId;validationIdentity='RAMSAI\RepatoQA';succeeded=$true;candidateCommit=$pending.CandidateSourceCommit;candidateSha256=$pending.CandidateSha256;qaWorkflowId=$pending.QaWorkflowId;testId=$pending.TestId;isolationPassed=$true;qaAddinRoot='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\RepatoQA';runnerManifestPath='C:\Users\RepatoQA\AppData\Roaming\Autodesk\Revit\Addins\2025\Repato.CreatePlanViews.TestRunner.addin';runnerManifestSha256='AF4DBFA78E61524DE7BD3B84178C6B70ED8D29D0A95BA17780826E09BE689D4F';manifestIntegrityPassed=$true};switch($counter.Mode){'wrong-commit'{$response.candidateCommit='0'*40};'wrong-hash'{$response.candidateSha256='0'*64};'request-mismatch'{$response.requestId=[guid]::NewGuid().ToString('N')};'manifest-mismatch'{$response.runnerManifestSha256='0'*64};'identity-mismatch'{$response.validationIdentity='RAMSAI\Other'};'isolation-failure'{$response.isolationPassed=$false}};$counter.LastResponse=$response;$response}catch{$counter.InvokerError=$_.Exception.Message;throw}}.GetNewClosure()
    switch($mode){
      'wrong-evidence-hash' {Invoke-RepatoStoreMutation $store {param($d,$preview)(Find-RepatoTask $d $taskId).deploymentWorkflows[0].qaBuildEvidence.ArtifactSha256='0'*64;$d}|Out-Null}
      'active-approval' {Invoke-RepatoStoreMutation $store {param($d,$preview)(Find-RepatoTask $d $taskId).approvalRequests=@([pscustomobject]@{action='qa-run';status='pending'});$d}|Out-Null}
      'consumed-approval-history' {Invoke-RepatoStoreMutation $store {param($d,$preview)(Find-RepatoTask $d $taskId).approvalRequests=@([pscustomobject]@{requestId='old-approved-consumed';action='qa-run';status='approved';consumedUtc='2026-10-14T03:46:46Z'},[pscustomobject]@{requestId='second-approved-consumed';action='qa-run';status='approved';consumedUtc='2026-10-14T03:46:46Z'});$d}|Out-Null}
      'tara-active' {Invoke-RepatoStoreMutation $store {param($d,$preview)(Find-RepatoTask $d $taskId)|Add-Member NoteProperty mayaTaraExecution ([pscustomobject]@{active=$true}) -Force;$d}|Out-Null}
      'no-validation-array' {Invoke-RepatoStoreMutation $store {param($d,$preview)$t=Find-RepatoTask $d $taskId;$t.PSObject.Properties.Remove('deploymentValidationOperations');$d}|Out-Null}
      'stale-prior-operation' {Invoke-RepatoStoreMutation $store {param($d,$preview)$t=Find-RepatoTask $d $taskId;$t.deploymentValidationOperations=@([pscustomobject]@{OperationId='old-operation';RequestId='old-request';TaskId=$taskId;WorkflowId=$workflowId;BuildRequestId='build-old';CandidateSourceCommit=('a'*40);CandidateSha256=('b'*64);QaWorkflowId='create-plan-views-v1';TestId='create-plan-views-v1';ValidationPurpose='IndependentAfterAmbiguousStaging';RequestDisposition='completed';ExpectedTaskRevision=11;ValidationRequest=[pscustomobject]@{requestId='old-request';candidateEvidence=[pscustomobject]@{CandidateSourceCommit=('a'*40);CandidateDllSha256=('b'*64);RunnerManifestSha256=$manifestHash}};ValidationRequestSha256=('c'*64)});$d}|Out-Null}
    }
