function Invoke-Recovery($f,[long]$revision){Invoke-MayaQaIndependentDeploymentValidationRecovery -StoreRoot $f.Store -TaskId $taskId -WorkflowId $workflowId -ExpectedTaskRevision $revision -ExpectedBuildRequestId $buildId -ExpectedCandidateSourceCommit $commit -ExpectedCandidateSha256 $candidateHash -ExpectedRunnerManifestPath $installedManifest -ExpectedRunnerManifestSha256 $manifestHash -HealthInvoker $f.Health -PreflightInvoker $f.Preflight -DeploymentValidationInvoker $f.Invoker -RevitProcessProvider $f.Revit}
try {
  Case 'successful independent validation and provenance preservation' {$f=New-Fixture 'success';$r=Invoke-Recovery $f $f.Revision;$state=Read-RepatoTaskStore $f.Store;$t=Find-RepatoTask $state $taskId;$e=$t.deploymentWorkflows[0].qaBuildEvidence;if($r.Status -cne 'IndependentDeploymentValidated' -or $r.StagingSuccessClaimed -or $r.StageRequestResent -or $r.RevitLaunched -or $r.ApprovalRequested -or $e.IndependentDeploymentValidation.Purpose -cne 'independent-current-deployment-validation' -or $e.IndependentDeploymentValidation.StagingDisposition -cne 'ambiguous-unresolved' -or $e.OriginalRunnerManifestPath -cne 'C:\Repato-Autonomous\Worktrees\create-plan-views-buildfix-4f2cbba22ba9\QA\Repato.CreatePlanViews.TestRunner.addin' -or @($state.stagingRequestDispositions|Where-Object RequestId -ceq ('9'*32)).Count -ne 1 -or $f.Counter.Calls -ne 1){throw 'success binding, distinct staging disposition, or preserved provenance failed'}}
  Case 'new candidate validation ignores and preserves older candidate operation' {$f=New-Fixture 'stale-prior-operation';$r=Invoke-Recovery $f $f.Revision;$state=Read-RepatoTaskStore $f.Store;$t=Find-RepatoTask $state $taskId;$old=@($t.deploymentValidationOperations|Where-Object OperationId -ceq 'old-operation');$current=@($t.deploymentValidationOperations|Where-Object BuildRequestId -ceq $buildId);if($r.Status -cne 'IndependentDeploymentValidated' -or $old.Count -ne 1 -or $current.Count -ne 1 -or $f.Counter.Calls -ne 1){throw "old candidate operation was reused or not preserved: status=$($r.Status), old=$($old.Count), current=$($current.Count), calls=$($f.Counter.Calls)"}}
  Case 'consumed approval history is preserved and does not block independent validation' {$f=New-Fixture 'consumed-approval-history';$r=Invoke-Recovery $f $f.Revision;$t=Find-RepatoTask (Read-RepatoTaskStore $f.Store) $taskId;if($r.Status -cne 'IndependentDeploymentValidated' -or @($t.approvalRequests|Where-Object {$_.status -ceq 'approved' -and $_.consumedUtc}).Count -ne 2){throw 'consumed historical approvals blocked validation or were modified'}}
  Case 'exact post-stage candidate hash mismatch is recoverable without restaging' {$f=New-Fixture 'stale-candidate-pin';$r=Invoke-Recovery $f $f.Revision;if($r.Status -cne 'IndependentDeploymentValidated' -or $r.StageRequestResent -or $f.Counter.Calls -ne 1){throw 'exact staged-candidate hash mismatch was not independently validated'}}
  Case 'fresh lifecycle when validation operation collection is absent' {$f=New-Fixture 'no-validation-array';$r=Invoke-Recovery $f $f.Revision;if($r.Status -cne 'IndependentDeploymentValidated'){throw 'missing validation collection prevented safe fresh operation'}}
  foreach($mode in @('wrong-commit','wrong-hash','request-mismatch','manifest-mismatch','identity-mismatch','isolation-failure')){Case "$mode rejected" {$f=New-Fixture $mode;$failed=$false;try{Invoke-Recovery $f $f.Revision}catch{$failed=$true};$t=Find-RepatoTask (Read-RepatoTaskStore $f.Store) $taskId;if(!$failed -or $t.deploymentWorkflows[0].qaBuildEvidence.DeploymentValidation){throw "$mode was accepted or recorded as deployment evidence"}}}
  foreach($mode in @('wrong-evidence-hash','wrong-agent','wrong-preflight-manifest','wrong-candidate-actual','active-approval','tara-active','running-revit')){Case "$mode guarded" {$f=New-Fixture $mode;$failed=$false;try{Invoke-Recovery $f $f.Revision}catch{$failed=$true};if(!$failed -or $f.Counter.Calls -ne 0){throw "$mode crossed the validation boundary"}}}
  Case 'stale revision rejected' {$f=New-Fixture 'success';$failed=$false;try{Invoke-Recovery $f ($f.Revision-1)}catch{$failed=$true};if(!$failed -or $f.Counter.Calls){throw 'stale revision crossed the validation boundary'}}
  Case 'ambiguous timeout is never resent' {$f=New-Fixture 'timeout';$failed=$false;try{Invoke-Recovery $f $f.Revision}catch{$failed=$true};$state=Find-RepatoTask (Read-RepatoTaskStore $f.Store) $taskId;$attempt=$false;try{Invoke-Recovery $f ([long]$state.revision)}catch{$attempt=$true};if(!$failed -or !$attempt -or $f.Counter.Calls -ne 1 -or $state.deploymentWorkflows[0].qaBuildEvidence.DeploymentValidation){throw 'ambiguous request was resent or promoted to success'}}
  [pscustomobject]@{Passed=$passed;Total=$total;AllStoresSynthetic=$true;StageRequestResent=$false;RevitLaunched=$false;ApprovalRequested=$false}|ConvertTo-Json -Compress
}finally{Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue}
